import pandas as pd
from selenium import webdriver
from selenium.webdriver.chrome.service import Service
from webdriver_manager.chrome import ChromeDriverManager
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

# 1. Name of the file we want to read (generated by the first bot)
filename = "google_maps_leads.xlsx"

print(f"📂 Reading data file: {filename}...")

try:
    # Read the Excel file
    df = pd.read_excel(filename)
except FileNotFoundError:
    print("❌ Error: File not found! Make sure you ran the first script first (bot_maps_final.py).")
    exit()

# 2. Prepare the new column
# If there is no column named "Phone", create it
if 'Phone' not in df.columns:
    df['Phone'] = None

# 3. Start the browser
print("🚀 Starting the browser...")
driver = webdriver.Chrome(service=Service(ChromeDriverManager().install()))
driver.maximize_window()
wait = WebDriverWait(driver, 10)

print(f"🔍 We have {len(df)} companies in the list. I will start processing them one by one...")

# 4. Loop through each row in the Excel file
for index, row in df.iterrows():
    
    # Smart feature: if the phone number already exists, skip this row (no need to waste time)
    # This is very useful if you want to stop the program and resume later from where it stopped
    if pd.notna(row['Phone']) and str(row['Phone']) != 'nan':
        continue

    name = row['Name']
    link = row['Google Maps Link']
    
    print(f"➡️ [{index+1}/{len(df)}] Opening: {name}")

    try:
        # Go to the direct link
        driver.get(link)
        
        # Search for the phone button
        # This line searches for any button whose hidden code contains the word 'phone:'
        # This is the most reliable method because Google changes the button style but not its function
        phone_btn = wait.until(EC.presence_of_element_located(
            (By.XPATH, "//button[contains(@data-item-id, 'phone:')]")
        ))
        
        # The number is usually in the 'aria-label' attribute
        phone_number = phone_btn.get_attribute("aria-label")
        
        # Clean the number from extra text (Arabic, English, French)
        if phone_number:
            phone_number = phone_number.replace("Phone:", "")\
                                       .replace("الهاتف:", "")\
                                       .replace("Numéro de téléphone:", "")\
                                       .replace("de téléphone:", "")\
                                       .strip()
                                       
            print(f"    📞 Phone number found: {phone_number}")
            
            # Update the value in memory
            df.at[index, 'Phone'] = phone_number
        else:
            print("    ⚠️ The button exists but contains no text.")

    except Exception:
        print("    ❌ No phone number found (or the page is different).")
        df.at[index, 'Phone'] = "Not Found"  # Record that no number exists so we don't retry it

    # 5. Periodic save (checkpoint)
    # Every 5 companies, we save the file. If the power goes out now, you won't lose what you've collected!
    if (index + 1) % 5 == 0:
        df.to_excel(filename, index=False)
        print("    💾 (Progress saved...)")
    
    # Short break to avoid blocking
    time.sleep(1.5)

# Final save at the end
df.to_excel(filename, index=False)
driver.quit()

print("\n" + "="*50)
print("✅ Task completed successfully! Congratulations, the Excel file now contains the phone numbers.")
print("="*50)